-- Post-seed assertions
SELECT CASE WHEN COUNT(*) = 3 THEN 'OSP count OK: 3' ELSE ('OSP count FAIL: ' || COUNT(*)::text) END AS osp_check FROM locations WHERE type = 'OSP';
SELECT CASE WHEN COUNT(*) = 36 THEN 'String count OK: 36' ELSE ('String count FAIL: ' || COUNT(*)::text) END AS string_check FROM strings;
SELECT CASE WHEN COUNT(*) = 177 THEN 'Tower count OK: 177' ELSE ('Tower count FAIL: ' || COUNT(*)::text) END AS tower_check FROM towers;